sections.css:
.typography-microcopy-md {
  font-family: var(--typography-microcopy-md-font-family);
  font-size: var(--typography-microcopy-md-font-size);
  font-weight: var(--typography-microcopy-md-font-weight);
  line-height: var(--typography-microcopy-md-line-height);
  letter-spacing: var(--typography-microcopy-md-letter-spacing);
}
.typography-display-sm {
  font-family: var(--typography-display-sm-font-family);
  font-size: var(--typography-display-sm-font-size);
  font-weight: var(--typography-display-sm-font-weight);
  line-height: var(--typography-display-sm-line-height);
  letter-spacing: var(--typography-display-sm-letter-spacing);
}
.typography-label-md {
  font-family: var(--typography-label-md-font-family);
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-label-md-font-weight);
  line-height: var(--typography-label-md-line-height);
  letter-spacing: var(--typography-label-md-letter-spacing);
}
.typography-body-sm {
  font-family: var(--typography-body-sm-font-family);
  font-size: var(--typography-body-sm-font-size);
  font-weight: var(--typography-body-sm-font-weight);
  line-height: var(--typography-body-sm-line-height);
  letter-spacing: var(--typography-body-sm-letter-spacing);
}
.typography-microcopy-2xs {
  font-family: var(--typography-microcopy-2xs-font-family);
  font-size: var(--typography-microcopy-2xs-font-size);
  font-weight: var(--typography-microcopy-2xs-font-weight);
  line-height: var(--typography-microcopy-2xs-line-height);
  letter-spacing: var(--typography-microcopy-2xs-letter-spacing);
}
.bcn-swf {
  flex-direction: column;
  min-height: 100%;
  display: flex;
}
.bcn-swf__head {
  align-items: center;
  gap: var(--spacing-300);
  padding: var(--spacing-200) 0 var(--spacing-400);
  flex-wrap: wrap;
  display: flex;
}
.bcn-swf__home {
  align-items: center;
  gap: var(--spacing-300);
  color: inherit;
  border-radius: var(--radius-200);
  text-decoration: none;
  display: inline-flex;
}
.bcn-swf__mark {
  border-radius: var(--radius-full);
  background: var(--bcn-teal-600, var(--color-background-brand));
  width: 20px;
  height: 20px;
  color: var(--color-content-default-knockout);
  flex-shrink: 0;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.bcn-swf__title {
  font-family: var(--font-decorative, var(--typography-font-family-sans));
  font-size: var(--font-size-300);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
  line-height: 1.2;
}
.bcn-swf__sub {
  font-size: var(--font-size-150);
  color: var(--color-content-default-secondary);
  margin: 0;
  line-height: 1;
}
.bcn-swf__nav {
  padding: 0 0 var(--spacing-500);
}
.bcn-swf__steps {
  align-items: center;
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
}
.bcn-swf__item {
  flex: 1;
  align-items: center;
  min-width: 0;
  display: flex;
}
.bcn-swf__step {
  align-items: center;
  gap: var(--spacing-200);
  padding: var(--spacing-200) var(--spacing-300);
  border-radius: var(--radius-200);
  font-size: var(--font-size-100);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  white-space: nowrap;
  text-decoration: none;
  transition:
    background-color 0.15s,
    color 0.15s;
  display: inline-flex;
}
.bcn-swf__icon {
  color: var(--_step);
  flex-shrink: 0;
  display: inline-flex;
}
.bcn-swf__label {
  line-height: 1;
}
.bcn-swf__check {
  margin-left: var(--spacing-100);
  color: var(--_step);
  flex-shrink: 0;
  display: inline-flex;
}
.bcn-swf__connector {
  height: 0;
  margin: 0 var(--spacing-200);
  border-top: 2px dotted var(--color-border-default);
  flex: 1;
}
.bcn-swf__item--fork,
.bcn-swf__item:last-child {
  flex: none;
}
.bcn-swf__step:hover,
.bcn-swf__step[data-active] {
  background: var(--_step);
  color: var(--color-content-default-knockout);
}
.bcn-swf__step:hover .bcn-swf__icon,
.bcn-swf__step:hover .bcn-swf__check,
.bcn-swf__step[data-active] .bcn-swf__icon,
.bcn-swf__step[data-active] .bcn-swf__check {
  color: var(--color-content-default-knockout);
}
.bcn-swf__body {
  flex: 1;
  min-width: 0;
}
.modern-layout {
  flex-direction: column;
  height: 100vh;
  display: flex;
}
.topbar {
  background: var(--bcn-gray-100);
  border-bottom: 1px solid var(--bcn-gray-300);
  z-index: 1100;
  height: 52px;
  padding: 0 var(--spacing-200);
  grid-template-columns: auto 1fr auto;
  align-items: center;
  display: grid;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
}
.topbar {
  padding: 0 var(--spacing-400);
}
.topbar__left {
  align-items: center;
  gap: var(--spacing-200);
  display: flex;
}
.sidebar-toggle {
  border-radius: var(--spacing-050);
  width: 32px;
  height: 32px;
  color: var(--bcn-gray-600);
  cursor: pointer;
  background: 0 0;
  border: none;
  justify-content: center;
  align-items: center;
  padding: 0;
  transition:
    background 0.15s,
    color 0.15s;
  display: flex;
}
.sidebar-toggle__icon {
  transition: transform 0.15s;
}
.tenant-trigger {
  align-items: center;
  gap: var(--spacing-100);
  padding: var(--spacing-100) var(--spacing-200);
  border-radius: var(--spacing-050);
  color: var(--bcn-gray-900);
  cursor: pointer;
  background: 0 0;
  border: none;
  font-size: 0.875rem;
  font-weight: 600;
  transition: background 0.15s;
  display: flex;
}
.topbar__center {
  justify-content: center;
  align-items: center;
  gap: var(--spacing-400);
  min-width: 0;
  padding: 0 var(--spacing-400);
  display: flex;
}
.bcn-search-trigger {
  align-items: center;
  gap: var(--spacing-200);
  width: 100%;
  max-width: 520px;
  padding: var(--spacing-150) var(--spacing-300);
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  cursor: text;
  margin: 0 auto;
  transition:
    border-color 0.15s,
    background 0.15s;
  display: flex;
}
.bcn-search-trigger .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-search-trigger__placeholder {
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
  font-size: var(--font-size-200);
  color: var(--color-content-default-tertiary);
  flex: 1;
  overflow: hidden;
}
.bcn-search-trigger__kbd {
  flex: none;
  gap: 2px;
  display: inline-flex;
}
.bcn-search-trigger__kbd kbd {
  min-width: 18px;
  height: 18px;
  font-family: inherit;
  font-size: 11px;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-tertiary);
  background: var(--color-background-elevation-sunken);
  border: 1px solid var(--color-border-default);
  border-radius: 4px;
  justify-content: center;
  align-items: center;
  padding: 0 4px;
  display: inline-flex;
}
.topbar__right {
  justify-content: flex-end;
  align-items: center;
  gap: var(--spacing-100);
  display: flex;
}
.qa-warning {
  align-items: center;
  gap: var(--spacing-100);
  padding: var(--spacing-050) var(--spacing-200);
  background: var(--color-background-accent);
  color: var(--color-background-elevation-raised);
  border-radius: var(--spacing-100);
  white-space: nowrap;
  font-size: 0.8125rem;
  font-weight: 600;
  display: inline-flex;
}
.icon-button {
  border-radius: var(--spacing-050);
  width: 32px;
  height: 32px;
  color: var(--color-content-default-secondary);
  cursor: pointer;
  background: 0 0;
  border: none;
  justify-content: center;
  align-items: center;
  padding: 0;
  text-decoration: none;
  transition:
    background 0.15s,
    color 0.15s;
  display: flex;
}
.user-menu {
  position: relative;
}
.user-menu-trigger {
  cursor: pointer;
  background: 0 0;
  border: none;
  border-radius: 9999px;
  justify-content: center;
  align-items: center;
  width: 44px;
  height: 44px;
  padding: 0;
  transition: transform 0.15s;
  display: flex;
}
.user-menu-trigger__avatar {
  object-fit: cover;
  border: 2px solid var(--bcn-gray-200);
  border-radius: 9999px;
  width: 32px;
  height: 32px;
  transition: border-color 0.15s;
}
.user-menu-trigger__avatar--fallback {
  background: var(--bcn-gray-200);
  color: var(--bcn-gray-500);
  justify-content: center;
  align-items: center;
  display: flex;
}
.user-panel {
  top: calc(100% + var(--spacing-200));
  background: var(--color-background-elevation-raised);
  border-radius: var(--spacing-200);
  border: 1px solid var(--bcn-gray-200);
  z-index: 1200;
  min-width: 280px;
  position: absolute;
  right: 0;
  box-shadow: 0 4px 24px #0000001f;
}
.user-panel[hidden] {
  display: none;
}
.modern-layout__body {
  flex: 1;
  padding-top: 52px;
  display: flex;
  overflow: hidden;
}
.side-nav {
  background-color: var(--bcn-gray-50);
  border-right: 1px solid var(--bcn-gray-200);
  flex-direction: column;
  flex-shrink: 0;
  width: 280px;
  height: 100%;
  font-size: 0.875rem;
  transition: width 0.2s ease-in-out;
  display: flex;
  overflow: visible;
}
.sidebar-header {
  padding: var(--spacing-300) var(--spacing-400);
  flex-shrink: 0;
  transition: padding 0.2s ease-in-out;
}
.site-logo {
  padding: var(--spacing-200);
  border-radius: var(--spacing-050);
  align-items: center;
  text-decoration: none;
  transition: background 0.15s;
  display: inline-flex;
}
.site-logo__img {
  width: var(--spacing-700);
  object-fit: contain;
  object-position: left center;
  height: 3.75rem;
  transition: all 0.2s ease-in-out;
}
.project-switcher-container {
  padding: 0 var(--spacing-400) var(--spacing-300);
  flex-shrink: 0;
  min-width: 0;
  transition: padding 0.2s ease-in-out;
}
.project-switcher__trigger {
  align-items: center;
  gap: var(--spacing-200);
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: var(--spacing-200) var(--spacing-300);
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--bcn-gray-200);
  border-radius: var(--spacing-200);
  cursor: pointer;
  color: var(--bcn-gray-950);
  font-size: 0.875rem;
  font-weight: 500;
  transition: all 0.15s;
  display: flex;
}
.project-switcher__trigger > .esa-icon:first-child {
  color: var(--bcn-gray-500);
  flex-shrink: 0;
}
.project-switcher__name {
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
  min-width: 0;
  overflow: hidden;
}
.main-nav {
  padding: 0 var(--spacing-400);
  gap: var(--spacing-050);
  scrollbar-width: none;
  -ms-overflow-style: none;
  flex-direction: column;
  flex: 1;
  transition: padding 0.2s ease-in-out;
  display: flex;
  overflow: visible auto;
}
.nav-section {
  flex-direction: column;
  display: flex;
  position: relative;
}
.nav-section__header {
  align-items: center;
  gap: var(--spacing-300);
  padding: var(--spacing-250) var(--spacing-200);
  color: var(--bcn-gray-950);
  border-radius: var(--spacing-050);
  white-space: nowrap;
  text-align: left;
  cursor: pointer;
  background: 0 0;
  border: none;
  width: 100%;
  font-size: 0.9375rem;
  font-weight: 550;
  text-decoration: none;
  transition: all 0.15s;
  display: flex;
}
.nav-section__header--link {
  color: var(--bcn-gray-950);
  text-decoration: none;
}
.nav-section__header:hover .esa-icon,
.nav-section--active .nav-section__header,
.nav-section--active .nav-section__header .esa-icon {
  color: var(--color-background-brand);
}
.nav-section__header > .esa-icon:first-child {
  color: var(--bcn-gray-950);
  flex-shrink: 0;
  transition: color 0.15s;
}
.nav-section__title {
  flex: 1;
  transition: opacity 0.2s ease-in-out;
  overflow: hidden;
}
.nav-section__header > .esa-icon:last-child {
  color: var(--bcn-gray-400);
  flex-shrink: 0;
  transition:
    transform 0.15s,
    opacity 0.2s ease-in-out;
}
.nav-section--collapsed .nav-section__header > .esa-icon:last-child {
  transform: rotate(-90deg);
}
.nav-section__items {
  opacity: 1;
  flex-direction: column;
  max-height: 500px;
  margin: 0;
  padding: 0;
  list-style: none;
  transition:
    max-height 0.2s ease-in-out,
    opacity 0.2s ease-in-out;
  display: flex;
  overflow: hidden;
}
.nav-section--collapsed .nav-section__items {
  opacity: 0;
  max-height: 0;
}
.nav-item {
  padding: 0 0 0 2.5rem;
}
.nav-sublink {
  padding: var(--spacing-200);
  color: var(--bcn-gray-950);
  border-radius: var(--spacing-050);
  font-size: 0.8125rem;
  line-height: 1.2;
  text-decoration: none;
  transition: all 0.15s;
  display: block;
}
.nav-item + .nav-item {
  margin-top: var(--spacing-050);
}
.nav-divider {
  height: 1px;
  margin: var(--spacing-200) 0;
  background: var(--bcn-gray-200);
  border: 0;
  flex-shrink: 0;
}
.modern-layout__content {
  flex: 1;
  min-width: 0;
  overflow-y: auto;
}
.bcn-omni {
  z-index: 1300;
  padding: var(--spacing-500);
  justify-content: center;
  align-items: center;
  display: flex;
  position: fixed;
  inset: 0;
}
.bcn-omni[hidden] {
  display: none;
}
.bcn-help-bar {
  z-index: 1000;
  align-items: center;
  gap: var(--spacing-100);
  padding: var(--spacing-100) var(--spacing-150);
  color: var(--bcn-helpbar-fg);
  background: var(--bcn-helpbar-bg);
  backdrop-filter: blur(14px) saturate(1.4);
  border: 1px solid var(--bcn-helpbar-border);
  border-radius: var(--radius-400, 14px);
  display: flex;
  position: fixed;
  bottom: 20px;
  left: 50%;
  transform: translate(-50%);
  box-shadow: 0 8px 24px #00000047;
}
.bcn-help-bar__guidance {
  align-items: center;
  gap: var(--spacing-150);
  height: 40px;
  padding: 0 var(--spacing-250, 0.625rem);
  border-radius: var(--radius-200, 8px);
  color: var(--bcn-helpbar-fg);
  font-family: inherit;
  font-size: var(--font-size-200, 0.9375rem);
  font-weight: var(--typography-font-weight-medium);
  cursor: pointer;
  transition: background var(--transition-fast, 0.15s ease);
  background: 0 0;
  border: 0;
  line-height: 1;
  display: inline-flex;
}
.bcn-aldo-mark {
  border-radius: var(--radius-full);
  background: var(--bcn-aldo);
  color: var(--color-content-default-knockout);
  flex-shrink: 0;
  justify-content: center;
  align-items: center;
  line-height: 0;
  display: inline-flex;
}
.bcn-aldo-mark[data-size="sm"] {
  --icon-size-xs: 12px;
  width: 20px;
  height: 20px;
}
.bcn-aldo-mark__glyph {
  justify-content: center;
  align-items: center;
  line-height: 0;
  display: inline-flex;
}
.bcn-help-bar__guidance-label {
  white-space: nowrap;
}
.bcn-help-bar__divider {
  width: 1px;
  height: 22px;
  margin: 0 var(--spacing-050, 2px);
  background: var(--bcn-helpbar-divider);
  flex: none;
}
.bcn-help-bar__tooltip,
.bcn-help-bar__popover {
  display: inline-flex;
}
.bcn-help-bar__whatsnew {
  display: inline-flex;
  position: relative;
}
.bcn-help-bar__dot {
  background: var(--bcn-aldo);
  width: 8px;
  height: 8px;
  box-shadow: 0 0 0 2px var(--bcn-helpbar-bg-solid);
  pointer-events: none;
  border-radius: 50%;
  position: absolute;
  top: 7px;
  right: 7px;
}
.bcn-help-bar__panel {
  width: 340px;
  max-width: 84vw;
  color: var(--color-content-default);
}
.bcn-help-bar__panel-header {
  justify-content: space-between;
  align-items: baseline;
  gap: var(--spacing-200);
  margin: 0 0 var(--spacing-300);
  display: flex;
}
.bcn-help-bar__panel-title {
  font-size: var(--font-size-200, 0.9375rem);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.bcn-help-bar__panel-release {
  font-size: var(--font-size-150, 0.875rem);
  color: var(--color-content-default-tertiary);
  white-space: nowrap;
  margin: 0;
}
.bcn-help-bar__panel-list {
  gap: var(--spacing-200);
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
}
.bcn-help-bar__panel-link {
  padding: var(--spacing-150) var(--spacing-150);
  margin: 0 calc(var(--spacing-150) * -1);
  border-radius: var(--radius-200, 8px);
  color: inherit;
  transition: background var(--transition-fast, 0.15s ease);
  text-decoration: none;
  display: block;
}
.bcn-help-bar__panel-item-title {
  font-family: var(--font-decorative);
  font-size: 1.0625rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0 0 2px;
  line-height: 1.3;
}
.bcn-help-bar__panel-item-blurb {
  font-size: var(--font-size-150, 0.875rem);
  font-weight: var(--typography-font-weight-regular, 400);
  color: var(--color-content-default-secondary);
  margin: 0;
  line-height: 1.45;
}
.bcn-help-bar__panel-footer {
  margin-top: var(--spacing-300);
  padding-top: var(--spacing-250, 0.625rem);
  border-top: 1px solid var(--color-border-default);
}
.bcn-help-bar__panel-all {
  font-size: var(--font-size-150, 0.875rem);
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-link);
  align-items: center;
  gap: 4px;
  text-decoration: none;
  display: inline-flex;
}
.bcn-help-bar__panel-all-arrow {
  transition: transform 0.15s;
}
.bcn-gd {
  --z-modal-backdrop: 1300;
  --z-modal: 1301;
  --side-dialog-width: 460px;
  --side-dialog-backdrop-filter: blur(2px);
}
.bcn-gd__header {
  align-items: center;
  gap: var(--spacing-300);
  min-width: 0;
  display: flex;
}
.bcn-aldo-mark[data-size="md"] {
  width: 40px;
  height: 40px;
}
.bcn-gd__title {
  font-family: var(--font-decorative);
  font-size: var(--font-size-400);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  line-height: 1.2;
}
.bcn-gd__stream {
  gap: var(--spacing-500);
  flex-direction: column;
  display: flex;
}
.bcn-gd-msg {
  gap: var(--spacing-300);
  align-items: flex-start;
  display: flex;
}
.bcn-gd-msg__avatar {
  flex: none;
  margin-top: 2px;
}
.bcn-gd-msg__group {
  gap: var(--spacing-500);
  flex-direction: column;
  flex: 1;
  min-width: 0;
  display: flex;
}
.bcn-gd__section {
  gap: var(--spacing-300);
  flex-direction: column;
  display: flex;
}
.bcn-gd__label {
  align-items: center;
  gap: var(--spacing-200);
  font-size: var(--font-size-250);
  font-weight: var(--typography-font-weight-bold);
  color: var(--color-content-default);
  margin: 0;
  display: flex;
}
.bcn-gd__label .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-gd__here {
  padding: var(--spacing-300) var(--spacing-400);
  background: var(--bcn-aldo-50);
  border: 1px solid var(--bcn-aldo-100);
  border-radius: var(--radius-200);
  flex-direction: column;
  gap: 4px;
  display: flex;
}
.bcn-gd__here-page {
  font-size: var(--font-size-250);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.bcn-gd__here-purpose {
  font-size: var(--font-size-150);
  color: var(--color-content-default-secondary);
  line-height: 1.5;
}
.bcn-gd__rows {
  flex-direction: column;
  display: flex;
}
.bcn-gd__foot {
  gap: var(--spacing-250);
  flex-direction: column;
  display: flex;
}
.bcn-gd__browse {
  align-self: flex-end;
  align-items: center;
  gap: var(--spacing-150);
  font-size: var(--font-size-150);
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-background-brand);
  text-decoration: none;
  display: inline-flex;
}
.bcn-gd-composer {
  align-items: flex-end;
  gap: var(--spacing-200);
  padding: var(--spacing-150) var(--spacing-150) var(--spacing-150) var(--spacing-300);
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-300);
  transition:
    border-color 0.15s,
    box-shadow 0.15s;
  display: flex;
}
.bcn-gd-composer__input {
  resize: none;
  min-width: 0;
  font-family: inherit;
  font-size: var(--font-size-200);
  color: var(--color-content-default);
  background: 0 0;
  border: 0;
  outline: 0;
  flex: 1;
  padding: 6px 0;
  line-height: 1.5;
  overflow-y: hidden;
}
.bcn-gd-composer__input::placeholder {
  color: var(--color-content-default-tertiary);
}
.bcn-gd-composer__send {
  border-radius: var(--radius-full);
  background: var(--bcn-aldo);
  width: 32px;
  height: 32px;
  color: var(--color-content-default-knockout);
  cursor: pointer;
  border: 0;
  flex: none;
  justify-content: center;
  align-items: center;
  transition:
    background 0.15s,
    color 0.15s;
  display: inline-flex;
}
.bcn-gd-composer__send:disabled {
  background: var(--color-background-elevation-sunken);
  color: var(--color-content-default-tertiary);
  cursor: default;
}
.bcn-gd-article {
  --z-modal-backdrop: 1302;
  --z-modal: 1303;
  --side-dialog-width: 460px;
  --side-dialog-backdrop-filter: blur(2px);
}
.bcn-gd-article__head {
  gap: var(--spacing-200);
  flex-direction: column;
  min-width: 0;
  display: flex;
}
.bcn-gd-article__back {
  align-items: center;
  gap: var(--spacing-100);
  font: inherit;
  font-size: var(--font-size-150);
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
  cursor: pointer;
  background: 0 0;
  border: 0;
  align-self: flex-start;
  padding: 0;
  display: inline-flex;
}
.bcn-gd-article__titlerow {
  align-items: center;
  gap: var(--spacing-200);
  min-width: 0;
  display: flex;
}
.bcn-gd-article__title {
  font-family: var(--font-decorative);
  font-size: var(--font-size-300);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  line-height: 1.25;
}
.bcn-gd-article__kind {
  border-radius: var(--radius-100);
  border: 1px solid var(--color-border-default);
  background: var(--color-background-elevation-raised);
  font-size: var(--font-size-100);
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
  white-space: nowrap;
  flex: none;
  padding: 1px 6px;
  line-height: 1.5;
}
.bcn-gd-article__panel[hidden] {
  display: none;
}
.bcn-bottom-drawer {
  --_width: var(--bcn-bottom-drawer-width, 90vw);
  --_height: var(--bcn-bottom-drawer-height, 80vh);
  --_inset: var(--bcn-bottom-drawer-inset, 0px);
  --_z: var(--bcn-bottom-drawer-z, 1400);
  display: contents;
}
.bcn-bottom-drawer__backdrop {
  background: var(--color-background-overlay-backdrop, #00000080);
  backdrop-filter: blur(2px);
  z-index: var(--_z);
  animation: 0.15s bcn-bd-fade;
  position: fixed;
  inset: 0;
}
.bcn-bottom-drawer:not([open]):not([closing]) .bcn-bottom-drawer__backdrop,
.bcn-bottom-drawer:not([open]):not([closing]) .bcn-bottom-drawer__panel {
  display: none;
}
.bcn-bottom-drawer__panel {
  left: 50%;
  bottom: var(--_inset);
  width: min(var(--_width), calc(100vw - var(--_inset) * 2));
  height: var(--_height);
  background: var(--color-background-elevation-raised);
  border-radius: var(--radius-300) var(--radius-300) 0 0;
  z-index: calc(var(--_z) + 1);
  outline: none;
  flex-direction: column;
  animation: 0.3s cubic-bezier(0.16, 1, 0.3, 1) bcn-bd-up;
  display: flex;
  position: fixed;
  overflow: hidden;
  transform: translate(-50%);
  box-shadow: 0 -12px 48px -12px #00000052;
}
.esa-icon {
  --_icon-size: var(--icon-size-md, 20px);
  width: var(--_icon-size);
  height: var(--_icon-size);
  color: inherit;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.esa-icon--xs {
  --_icon-size: var(--icon-size-xs, 14px);
}
.esa-icon svg {
  width: var(--_icon-size);
  height: var(--_icon-size);
  display: block;
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, 16px);
}
.esa-icon--md {
  --_icon-size: var(--icon-size-md, 20px);
}
.esa-progress-bar {
  --_progress-height: var(--progress-bar-height-md, 8px);
  --_progress-radius: var(--radius-pill, 9999px);
  --_progress-track-bg: var(--color-background-elevation-sunken, #f0f0f0);
  --_progress-fill-bg: var(--color-background-brand, #46a758);
  width: 100%;
  display: block;
}
.esa-progress-bar--xs {
  --_progress-height: var(--progress-bar-height-xs, 2px);
}
.esa-progress-bar__track {
  height: var(--_progress-height);
  border-radius: var(--_progress-radius);
  background: var(--_progress-track-bg);
  position: relative;
  overflow: hidden;
}
.esa-progress-bar__fill {
  border-radius: var(--_progress-radius);
  background: var(--_progress-fill-bg);
  height: 100%;
  transition: width 0.3s;
}
.esa-stat {
  --_stat-value-color: var(--stat-value-color, var(--color-content-default, #202020));
  --_stat-value-font: var(
    --typography-font-family-display,
    var(
      --typography-display-sm-font-family,
      var(--typography-font-family-display, "DM Sans", sans-serif)
    )
  );
  --_stat-value-size: var(
    --stat-value-size,
    var(--typography-display-sm-font-size, var(--font-size-700, 2.25rem))
  );
  --_stat-value-weight: var(
    --typography-font-weight-bold,
    var(--typography-display-sm-font-weight, var(--typography-font-weight-bold, 650))
  );
  --_stat-label-color: var(--color-content-default-secondary, #646464);
  --_stat-label-size: var(
    --font-size-200,
    var(--typography-label-md-font-size, var(--font-size-200, 0.9375rem))
  );
  --_stat-label-weight: var(
    --typography-font-weight-medium,
    var(--typography-label-md-font-weight, var(--typography-font-weight-medium, 500))
  );
  --_stat-sub-color: var(--color-content-default-secondary, #646464);
  --_stat-sub-size: var(
    --font-size-150,
    var(--typography-body-sm-font-size, var(--font-size-150, 0.875rem))
  );
  --_stat-accent-color: var(--stat-accent-color, var(--color-content-brand, #2a7e3b));
  --_stat-gap: var(--spacing-050, 0.125rem);
  gap: var(--_stat-gap);
  background: 0 0;
  flex-direction: column;
  display: flex;
}
.esa-stat__value {
  font-family: var(--_stat-value-font);
  font-size: var(--_stat-value-size);
  font-weight: var(--_stat-value-weight);
  color: var(--_stat-value-color);
}
.esa-stat__label {
  font-size: var(--_stat-label-size);
  font-weight: var(--_stat-label-weight);
  color: var(--_stat-label-color);
}
.esa-stat__sub {
  font-size: var(--_stat-sub-size);
  color: var(--_stat-sub-color);
}
.bcn-swcb {
  min-width: 22px;
  padding: 2px var(--spacing-150);
  border-radius: var(--radius-100);
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default-subtle);
  color: var(--color-content-default-tertiary);
  font-family: var(--typography-font-family-sans);
  flex-shrink: 0;
  justify-content: center;
  align-items: center;
  font-size: 0.6875rem;
  font-weight: 500;
  line-height: 1;
  display: inline-flex;
}
.bcn-cirun {
  gap: var(--spacing-400);
  padding: var(--spacing-500);
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  flex-direction: column;
  display: flex;
}
.bcn-cirun__phases {
  gap: var(--spacing-400);
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
}
.bcn-cirun__phase {
  gap: var(--spacing-150);
  flex-direction: column;
  min-width: 0;
  display: flex;
}
.bcn-cirun__phase-head {
  align-items: center;
  gap: var(--spacing-150);
  font-size: var(--font-size-100);
  color: var(--color-content-default-tertiary);
  flex-wrap: wrap;
  display: flex;
}
.bcn-cirun__phase[data-state="running"] .bcn-cirun__phase-head {
  color: var(--color-content-default);
}
.bcn-cirun__phase-n,
.bcn-cirun__phase-check {
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border-default);
  width: 18px;
  height: 18px;
  font-size: 0.6875rem;
  font-weight: var(--typography-font-weight-semibold);
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.bcn-cirun__phase[data-state="running"] .bcn-cirun__phase-n {
  background: var(--color-background-brand);
  border-color: var(--color-background-brand);
  color: var(--color-content-on-brand);
}
.bcn-cirun__phase-check {
  display: none;
}
.bcn-cirun__phase-label {
  font-weight: var(--typography-font-weight-semibold);
}
.bcn-cirun__phase-count {
  font-variant-numeric: tabular-nums;
  margin-left: auto;
}
.bcn-cirun__stats {
  gap: var(--spacing-400);
  padding-top: var(--spacing-300);
  border-top: 1px solid var(--color-border-default-subtle);
  grid-template-columns: repeat(6, minmax(0, 1fr));
  display: grid;
}
.bcn-cirun__bar {
  align-items: center;
  gap: var(--spacing-300);
  flex-wrap: wrap;
  display: flex;
}
.bcn-cirun__status {
  font-size: var(--font-size-150);
  color: var(--color-content-default);
  margin: 0;
}
.bcn-cirun__clock {
  font-family: var(--typography-font-family-mono);
  font-size: var(--font-size-100);
  color: var(--color-content-default-tertiary);
  font-variant-numeric: tabular-nums;
}
.bcn-cirun__controls {
  gap: var(--spacing-200);
  align-items: center;
  margin-left: auto;
  display: flex;
}
.bcn-cirun__log {
  height: 26rem;
  padding: var(--spacing-200) var(--spacing-300);
  border: 1px solid var(--color-border-default-subtle);
  border-radius: var(--radius-150, var(--radius-200));
  background: var(--color-background-elevation-sunken);
  font-family: var(--typography-font-family-mono);
  font-size: var(--font-size-100);
  line-height: 22px;
  overflow-y: auto;
}
.bcn-cirun__log .bcn-cirun__line {
  gap: var(--spacing-300);
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--color-content-default-tertiary);
  display: flex;
  overflow: hidden;
}
.bcn-cirun__log [data-level="heading"] {
  color: var(--color-content-default);
  font-weight: var(--typography-font-weight-semibold);
}
.bcn-cirun__log .bcn-cirun__stamp {
  color: var(--color-content-disabled);
  flex-shrink: 0;
}
.bcn-cirun__log .bcn-cirun__msg {
  text-overflow: ellipsis;
  overflow: hidden;
}
.bcn-cirun__log [data-level="info"] .bcn-cirun__msg {
  padding-left: var(--spacing-300);
}
.bcn-cirun__log [data-level="finding"] {
  color: var(--color-content-brand);
}
.page-layout {
  min-height: calc(100vh - 52px);
  padding: var(--spacing-600);
  background: var(--bcn-gray-50);
  box-sizing: border-box;
  flex-direction: column;
  display: flex;
}
.page-layout__container {
  flex-direction: column;
  display: flex;
}
.page-layout__content {
  padding: var(--spacing-500) 0;
  min-height: 70vh;
  position: relative;
}
.page-layout__bleed,
.page-layout section {
  width: 100%;
}
.stack {
  --gap: var(--spacing-400, 1rem);
  gap: var(--gap);
  flex-direction: column;
  display: flex;
}
.bcn-swsp {
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  flex-shrink: 0;
}
.bcn-swsp__header {
  padding: var(--spacing-400) var(--spacing-500);
}
.bcn-swsp__row {
  align-items: center;
  gap: var(--spacing-300);
  flex-wrap: wrap;
  display: flex;
}
.bcn-swsp__num {
  border-radius: var(--radius-full);
  background: var(--_step);
  width: 28px;
  height: 28px;
  color: var(--color-content-default-knockout);
  flex-shrink: 0;
  justify-content: center;
  align-items: center;
  font-size: 0.875rem;
  font-weight: 600;
  display: inline-flex;
}
.bcn-swsp__title {
  align-items: center;
  gap: var(--spacing-150);
  font-family: var(--font-decorative);
  color: var(--color-content-default);
  flex-wrap: wrap;
  margin: 0;
  font-size: 1.125rem;
  font-weight: 600;
  line-height: 1.2;
  display: inline-flex;
}
.bcn-swsp__actions {
  align-items: center;
  gap: var(--spacing-200);
  margin-left: auto;
  display: inline-flex;
}
.bcn-swsp__actions:empty {
  display: none;
}
.bcn-swsp__intro {
  margin: var(--spacing-200) 0 0;
  color: var(--color-content-default);
  font-size: 0.875rem;
  line-height: 1.4;
}
.typography-label-md {
  font-family: var(--typography-label-md-font-family);
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-label-md-font-weight);
  line-height: var(--typography-label-md-line-height);
  letter-spacing: var(--typography-label-md-letter-spacing);
}
.esa-button {
  --_btn-pad-y: var(--spacing-300, 0.75rem);
  --_btn-padding-x: var(--spacing-300, 0.75rem);
  --_btn-radius: var(--button-radius-md, 0.5rem);
  --_accent: var(--color-background-brand, #46a758);
  --_accent-hover: var(--color-background-brand-hover, #3e9b4f);
  --_on: var(--color-content-default-knockout, #fcfcfc);
  --_accent-text: var(--_accent);
  --_btn-tint-hover: color-mix(in srgb, var(--_accent) 8%, transparent);
  --_btn-tint-active: color-mix(in srgb, var(--_accent) 14%, transparent);
  display: inline-block;
}
.esa-button__native {
  justify-content: center;
  align-items: center;
  gap: var(--spacing-200, 8px);
  width: 100%;
  padding-block: var(--_btn-pad-y);
  padding-inline: var(--_btn-padding-x);
  border: var(--border-width-default, 1px) solid transparent;
  border-radius: var(--_btn-radius);
  cursor: pointer;
  transition:
    background var(--transition-fast, 0.15s ease),
    border-color var(--transition-fast, 0.15s ease);
  -webkit-appearance: none;
  appearance: none;
  text-decoration: none;
  display: inline-flex;
}
.esa-button--appearance-fill .esa-button__native {
  background: var(--_accent);
  color: var(--_on);
  border-color: var(--_accent-border, transparent);
}
.esa-button--variant-chrome .esa-button__native {
  color: inherit;
  background: 0 0;
  border-color: #0000;
}
.esa-button--icon-only .esa-button__native {
  padding-inline: var(--_btn-pad-y);
  aspect-ratio: 1;
}
.esa-button--xs {
  --_btn-pad-y: var(--spacing-200, 0.5rem);
  --_btn-padding-x: var(--spacing-200, 0.5rem);
  --_btn-radius: var(--button-radius-xs, 4px);
}
.esa-button--variant-secondary {
  --_accent: var(--color-background-brand-muted);
  --_accent-hover: var(--color-background-brand-muted-hover);
  --_on: var(--color-content-on-brand-muted, var(--color-content-default));
  --_accent-text: var(--color-content-brand);
  --_accent-border: var(--color-border-default-strong, #bbb);
}
.esa-button__label {
  white-space: nowrap;
}
.esa-button--sm {
  --_btn-pad-y: var(--spacing-250, 0.625rem);
  --_btn-padding-x: var(--spacing-250, 0.625rem);
  --_btn-radius: var(--button-radius-sm, 4px);
}
.esa-button--variant-primary {
  --_accent-text: var(--color-content-brand);
}
html,
.modern-layout__content {
  scroll-behavior: smooth;
}

full.css:
:root,
[data-theme="beacon"] {
  --animation-overlay-enter: 0.25s ease-out;
  --bcn-aldo: #08908b;
  --bcn-aldo-100: #cfeceb;
  --bcn-aldo-50: #e8f6f5;
  --bcn-gray-100: #efefef;
  --bcn-gray-200: #dcdcdc;
  --bcn-gray-300: #bdbdbd;
  --bcn-gray-400: #989898;
  --bcn-gray-50: #fafafa;
  --bcn-gray-500: #7c7c7c;
  --bcn-gray-600: #656565;
  --bcn-gray-900: #3d3d3d;
  --bcn-gray-950: #292929;
  --bcn-helpbar-bg: #17191bc7;
  --bcn-helpbar-bg-solid: #1f2224;
  --bcn-helpbar-border: #ffffff1f;
  --bcn-helpbar-divider: #ffffff29;
  --bcn-helpbar-fg: #ffffffeb;
  --bcn-teal-600: #0e807b;
  --border-width-default: 1px;
  --button-radius-md: 0.25rem;
  --button-radius-sm: 0.25rem;
  --button-radius-xs: 0.25rem;
  --color-background-accent: #f76b15;
  --color-background-brand: #005862;
  --color-background-brand-hover: #00474f;
  --color-background-brand-muted: #eef5f4;
  --color-background-brand-muted-hover: #b9d6d2;
  --color-background-elevation-raised: #fcfcfc;
  --color-background-elevation-sunken: #efefef;
  --color-background-overlay-backdrop: #00000080;
  --color-border-default: #dcdcdc;
  --color-border-default-strong: #bdbdbd;
  --color-border-default-subtle: #efefef;
  --color-content-brand: #005862;
  --color-content-default: #3d3d3d;
  --color-content-default-knockout: #fcfcfc;
  --color-content-default-secondary: #525252;
  --color-content-default-tertiary: #656565;
  --color-content-disabled: #8d8d8d;
  --color-content-link: #005862;
  --color-content-on-brand: #fcfcfc;
  --color-content-on-brand-muted: #203c25;
  --elevation-4: 0 6px 24px -6px #00000012;
  --elevation-5: 0 8px 32px -8px #00000014;
  --font-decorative: "Besley", serif;
  --font-size-100: clamp(0.625rem, 0.56rem + 0.32vw, 0.75rem);
  --font-size-150: clamp(0.6875rem, 0.61rem + 0.38vw, 0.875rem);
  --font-size-200: clamp(0.75rem, 0.66rem + 0.44vw, 0.9375rem);
  --font-size-250: clamp(0.8125rem, 0.71rem + 0.5vw, 1.0625rem);
  --font-size-300: clamp(0.875rem, 0.77rem + 0.52vw, 1.125rem);
  --font-size-400: clamp(1rem, 0.88rem + 0.6vw, 1.25rem);
  --font-size-700: clamp(1.625rem, 1.41rem + 1.08vw, 2.25rem);
  --icon-size-md: 20px;
  --icon-size-sm: 16px;
  --icon-size-xs: 14px;
  --progress-bar-height-md: 8px;
  --progress-bar-height-xs: 2px;
  --radius-100: 0.25rem;
  --radius-200: 0.5rem;
  --radius-300: 0.5rem;
  --radius-400: 0.75rem;
  --radius-full: 9999px;
  --radius-md: 0.25rem;
  --radius-pill: 9999px;
  --side-dialog-inset: 16px;
  --side-dialog-width: 400px;
  --spacing-050: 0.125rem;
  --spacing-100: 0.25rem;
  --spacing-150: 0.375rem;
  --spacing-200: 0.5rem;
  --spacing-250: 0.625rem;
  --spacing-300: 0.75rem;
  --spacing-400: 1rem;
  --spacing-500: 1.5rem;
  --spacing-600: 2rem;
  --spacing-700: 3rem;
  --stat-accent-color: #005862;
  --stat-value-color: #3d3d3d;
  --stat-value-size: clamp(1.625rem, 1.41rem + 1.08vw, 2.25rem);
  --transition-fast: 0.15s ease;
  --typography-body-sm-font-family: "DM Sans", sans-serif;
  --typography-body-sm-font-size: clamp(0.6875rem, 0.61rem + 0.38vw, 0.875rem);
  --typography-body-sm-font-weight: 350;
  --typography-body-sm-letter-spacing: 0.01em;
  --typography-body-sm-line-height: 1.6;
  --typography-display-sm-font-family: "DM Sans", sans-serif;
